-- Uruguay: ES/DE/FR milestone translations for the 6 milestones in
-- migration 391. Hand-translated, not machine copy-paste.

-- uy-cfe-decree-2012
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-decree-2012', 'es', 'El Decreto 36/012 crea el régimen de CFE (Comprobante Fiscal Electrónico) de Uruguay', 'El 8 de febrero de 2012, el Poder Ejecutivo de Uruguay promulgó el Decreto 36/012, el decreto fundacional del sistema de Comprobante Fiscal Electrónico (CFE): define el propio CFE, obliga a los contribuyentes incluidos a documentar sus ventas exclusivamente mediante CFE autorizado, exige un certificado y una firma electrónica válidos, y establece que el incumplimiento del CFE se sanciona bajo el régimen general de sanciones por documentación tributaria de Uruguay, y no mediante un esquema de multas específico para el CFE. Este decreto es el fundamento legal de todo lo que vino después -- el sistema gestionado por la DGI que se construyó sobre él es uno de los regímenes de facturación electrónica obligatoria más antiguos de América Latina.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si está investigando el marco legal de la facturación electrónica de Uruguay, el Decreto 36/012 (y su referencia sancionatoria del Art. 17) es el texto fundacional por el que empezar"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-decree-2012', 'de', 'Der Decreto 36/012 schafft Uruguays CFE-Regime (Comprobante Fiscal Electrónico)', 'Am 8. Februar 2012 erließ die uruguayische Exekutive den Decreto 36/012, den Gründungserlass des Comprobante Fiscal Electrónico (CFE)-Systems: Er definiert den CFE selbst, verpflichtet die erfassten Steuerpflichtigen, ihre Verkäufe ausschließlich über autorisierte CFE zu dokumentieren, verlangt ein gültiges elektronisches Zertifikat und eine elektronische Signatur, und legt fest, dass CFE-Verstöße nach Uruguays allgemeinem Sanktionsregime für steuerliche Dokumentation geahndet werden, nicht nach einem eigenen CFE-Bußgeldkatalog. Dieser Erlass ist die rechtliche Grundlage für alles, was folgte -- das von der DGI betriebene System, das darauf aufbaut, ist eines der ältesten verpflichtenden E-Invoicing-Regime Lateinamerikas.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Sie den rechtlichen Rahmen der E-Rechnungsstellung in Uruguay recherchieren, ist der Decreto 36/012 (mit seinem Sanktionsverweis in Art. 17) der grundlegende Ausgangstext"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-decree-2012', 'fr', 'Le Decreto 36/012 crée le régime CFE (Comprobante Fiscal Electrónico) de l''Uruguay', 'Le 8 février 2012, le pouvoir exécutif uruguayen a promulgué le Decreto 36/012, le décret fondateur du système de Comprobante Fiscal Electrónico (CFE) : il définit le CFE lui-même, oblige les contribuables concernés à documenter leurs ventes exclusivement au moyen de CFE autorisés, exige un certificat et une signature électroniques valides, et établit que le non-respect des règles relatives au CFE est sanctionné selon le régime général de sanctions applicable à la documentation fiscale en Uruguay, plutôt que par un barème d''amendes propre au CFE. Ce décret constitue le fondement juridique de tout ce qui a suivi -- le système géré par la DGI qui s''est construit sur cette base est l''un des régimes de facturation électronique obligatoire les plus anciens d''Amérique latine.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si vous étudiez le cadre juridique de la facturation électronique en Uruguay, le Decreto 36/012 (et son renvoi sanctionnateur à l''Art. 17) est le texte fondateur par lequel commencer"]');

-- uy-cfe-framework-2012
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-framework-2012', 'es', 'La Resolución DGI 798/012 construye el marco operativo y abre la incorporación voluntaria', 'Emitida el 8 de mayo de 2012, la Resolución de Interés General 798/012 puso en práctica el Decreto 36/012: definió los tipos de documento CFE (e-Factura, e-Ticket, notas de crédito/débito, e-Remito, y otros), fijó el formato XML con firma electrónica, exigió un reporte diario consolidado a la DGI, y estableció comprobantes de contingencia para las interrupciones del sistema. Esta resolución es la que permitió a la DGI comenzar a designar contribuyentes para la incorporación voluntaria y, más adelante, obligatoria -- el mecanismo utilizado en cada una de las olas obligatorias posteriores.', '["No se requiere ninguna acción para este hito histórico -- establece el mecanismo técnico/legal sobre el que se apoyaron las olas obligatorias posteriores (ver más abajo)", "Si está evaluando los tipos de documento CFE de Uruguay, esta resolución es donde se definieron por primera vez el e-Factura, el e-Ticket y los demás tipos principales"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-framework-2012', 'de', 'Die Resolución DGI 798/012 schafft den operativen Rahmen und eröffnet die freiwillige Einbindung', 'Die am 8. Mai 2012 erlassene Resolución de Interés General 798/012 setzte den Decreto 36/012 operativ um: Sie definierte die CFE-Belegtypen (e-Factura, e-Ticket, Gutschriften/Lastschriften, e-Remito und weitere), legte das Format XML mit elektronischer Signatur fest, verlangte eine tägliche konsolidierte Meldung an die DGI und richtete Notfallbelege für Systemausfälle ein. Diese Resolution ermöglichte es der DGI, Steuerpflichtige für die freiwillige und später verpflichtende Einbindung zu benennen -- der Mechanismus, der für jede spätere verpflichtende Welle genutzt wurde.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er schafft den technischen/rechtlichen Mechanismus, auf dem die späteren verpflichtenden Wellen (siehe unten) aufbauten", "Wenn Sie die CFE-Belegtypen Uruguays prüfen: In dieser Resolution wurden e-Factura, e-Ticket und die übrigen Kerntypen erstmals definiert"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-framework-2012', 'fr', 'La Resolución DGI 798/012 bâtit le cadre opérationnel et ouvre l''intégration volontaire', 'Publiée le 8 mai 2012, la Resolución de Interés General 798/012 a rendu opérationnel le Decreto 36/012 : elle a défini les types de documents CFE (e-Factura, e-Ticket, notes de crédit/débit, e-Remito, et d''autres), fixé le format XML accompagné d''une signature électronique, exigé un rapport quotidien consolidé à la DGI, et instauré des reçus de contingence en cas d''interruption du système. C''est cette résolution qui a permis à la DGI de commencer à désigner des contribuables pour une intégration volontaire puis, plus tard, obligatoire -- le mécanisme utilisé pour chacune des vagues obligatoires suivantes.', '["Aucune action n''est requise pour ce jalon historique -- il établit le mécanisme technique/juridique sur lequel se sont appuyées les vagues obligatoires ultérieures (voir ci-dessous)", "Si vous évaluez les types de documents CFE de l''Uruguay, c''est dans cette résolution que l''e-Factura, l''e-Ticket et les autres types principaux ont été définis pour la première fois"]');

-- uy-phased-rollout-2014-2019
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-phased-rollout-2014-2019', 'es', 'La DGI implementa por fases la adopción obligatoria del CFE según el nivel de facturación del contribuyente, 2014-2019', 'A partir de 2014, la DGI superpuso la incorporación obligatoria al CFE sobre la adhesión voluntaria, comenzando por los grandes contribuyentes (Grandes Contribuyentes), las empresas clasificadas como CEDE y los operadores de zonas francas/duty-free, para luego extenderse en sucesivas olas anuales fijadas según el volumen de ventas del año anterior de cada contribuyente, medido en Unidades Indexadas (UI): los contribuyentes con ventas de aproximadamente UI 30 millones/15 millones en 2015 se incorporaron en 2016, UI 7 millones/4 millones (ventas de 2016) en 2017, UI 2,5 millones/1,5 millones (ventas de 2017) en 2018, y UI 750.000/305.000 (ventas de 2018) en 2019 -- cada ola sumaba miles de contribuyentes más. A fines de 2016, la DGI contabilizaba más de 5.000 emisores electrónicos acumulados que procesaban más de 1.280 millones de CFE al año.', '["Si su empresa fue designada en una ola anterior, confirme que su emisión de CFE se ha mantenido al día con cualquier resolución posterior de la DGI que actualice el formato técnico", "Este enfoque escalonado por nivel de facturación es el modelo que utilizó la DGI antes de pasar a los plazos casi universales descritos en los hitos siguientes -- un contexto útil si está investigando la historia de Uruguay más que sus requisitos actuales"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-phased-rollout-2014-2019', 'de', 'DGI führt die verpflichtende CFE-Einführung stufenweise nach Umsatzklasse des Steuerpflichtigen ein, 2014-2019', 'Ab 2014 legte die DGI eine verpflichtende CFE-Einbindung über die bereits bestehende freiwillige Teilnahme, beginnend mit Großsteuerpflichtigen (Grandes Contribuyentes), als CEDE eingestuften Unternehmen und Duty-free-Betreibern, und weitete dies dann in aufeinanderfolgenden jährlichen Wellen aus, gestaffelt nach dem Vorjahresumsatz jedes Steuerpflichtigen in Unidades Indexadas (UI): Steuerpflichtige mit rund UI 30 Millionen/15 Millionen Umsatz im Jahr 2015 wurden 2016 einbezogen, UI 7 Millionen/4 Millionen (Umsatz 2016) 2017, UI 2,5 Millionen/1,5 Millionen (Umsatz 2017) 2018 und UI 750.000/305.000 (Umsatz 2018) 2019 -- jede Welle brachte tausende weitere Steuerpflichtige hinzu. Ende 2016 zählte die DGI insgesamt über 5.000 elektronische Rechnungssteller, die mehr als 1,28 Milliarden CFE pro Jahr verarbeiteten.', '["Wenn Ihr Unternehmen in eine frühere Welle einbezogen wurde, prüfen Sie, ob Ihre CFE-Ausstellung mit späteren DGI-Resolutionen zur Aktualisierung des technischen Formats Schritt gehalten hat", "Dieser nach Umsatzklassen gestaffelte Ansatz war das Modell, das die DGI verwendete, bevor sie zu den in den folgenden Meilensteinen beschriebenen nahezu universellen Fristen überging -- nützlicher Kontext, wenn Sie sich eher für die Geschichte Uruguays als für die aktuellen Anforderungen interessieren"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-phased-rollout-2014-2019', 'fr', 'La DGI déploie par phases l''adoption obligatoire du CFE selon la tranche de chiffre d''affaires du contribuable, 2014-2019', 'À partir de 2014, la DGI a superposé l''intégration obligatoire au CFE à l''adhésion volontaire existante, en commençant par les grands contribuables (Grandes Contribuyentes), les entreprises classées CEDE et les opérateurs des zones franches, puis en s''étendant par vagues annuelles successives déterminées selon le chiffre d''affaires de l''année précédente de chaque contribuable, exprimé en Unidades Indexadas (UI) : les contribuables ayant réalisé environ UI 30 millions/15 millions de ventes en 2015 sont entrés dans le dispositif en 2016, UI 7 millions/4 millions (ventes 2016) en 2017, UI 2,5 millions/1,5 million (ventes 2017) en 2018, et UI 750 000/305 000 (ventes 2018) en 2019 -- chaque vague ajoutant des milliers de contribuables supplémentaires. Fin 2016, la DGI comptait plus de 5 000 émetteurs électroniques cumulés traitant plus de 1,28 milliard de CFE par an.', '["Si votre entreprise a été désignée lors d''une vague antérieure, vérifiez que votre émission de CFE a suivi les mises à jour techniques apportées par les résolutions ultérieures de la DGI", "Cette approche par paliers de chiffre d''affaires est le modèle qu''a utilisé la DGI avant de passer aux échéances quasi universelles décrites dans les jalons suivants -- un contexte utile si vous vous intéressez à l''histoire de l''Uruguay plutôt qu''à ses exigences actuelles"]');

-- uy-deadline-extension-2023
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-deadline-extension-2023', 'es', 'La Resolución DGI 2548/023 fija el plazo final para la adopción universal del CFE', 'Aprobada el 30 de noviembre de 2023 y publicada el 1 de diciembre de 2023, la Resolución DGI 2548/023 prorrogó un plazo de incorporación obligatoria anterior (fijado por la Resolución complementaria 2389/023): los contribuyentes ya alcanzados por esa designación tuvieron hasta el 31 de diciembre de 2024 para convertirse en emisores electrónicos, y quienes se registraran nuevamente en el IVA entre el 1 de mayo de 2024 y el 31 de diciembre de 2024 debían estar emitiendo electrónicamente antes del 1 de enero de 2025. Esta resolución estableció el plazo que efectivamente concreta el hito del mandato universal descrito a continuación.', '["No se requiere ninguna acción para este hito histórico -- fija el plazo cuya entrada en vigor describe la siguiente entrada", "Si su empresa se registró en el IVA durante 2024, confirme cuál de los plazos de esta resolución se aplicó específicamente a su caso"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-deadline-extension-2023', 'de', 'Die Resolución DGI 2548/023 legt die endgültige Frist für die universelle CFE-Einführung fest', 'Die am 30. November 2023 genehmigte und am 1. Dezember 2023 veröffentlichte Resolución DGI 2548/023 verlängerte eine frühere Frist zur verpflichtenden Einbindung (festgelegt durch die begleitende Resolución 2389/023): Steuerpflichtige, die bereits von dieser Festlegung erfasst waren, erhielten bis zum 31. Dezember 2024 Zeit, um elektronische Rechnungssteller zu werden, und wer sich zwischen dem 1. Mai 2024 und dem 31. Dezember 2024 neu für die Umsatzsteuer registrierte, musste vor dem 1. Januar 2025 elektronisch abrechnen. Diese Resolution legte die Frist fest, die der unten beschriebene Meilenstein der universellen Pflicht tatsächlich umsetzt.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er legt die Frist fest, deren Inkrafttreten der nächste Eintrag beschreibt", "Wenn sich Ihr Unternehmen im Jahr 2024 für die Umsatzsteuer registriert hat, prüfen Sie, welche Frist dieser Resolution konkret für Sie galt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-deadline-extension-2023', 'fr', 'La Resolución DGI 2548/023 fixe l''échéance finale pour l''adoption universelle du CFE', 'Approuvée le 30 novembre 2023 et publiée le 1er décembre 2023, la Resolución DGI 2548/023 a prorogé une échéance antérieure d''intégration obligatoire (fixée par la résolution complémentaire 2389/023) : les contribuables déjà visés par cette désignation avaient jusqu''au 31 décembre 2024 pour devenir émetteurs électroniques, et toute personne s''enregistrant nouvellement à la TVA entre le 1er mai 2024 et le 31 décembre 2024 devait facturer électroniquement avant le 1er janvier 2025. Cette résolution a fixé l''échéance que le jalon de l''obligation universelle décrit ci-dessous concrétise réellement.', '["Aucune action n''est requise pour ce jalon historique -- il fixe l''échéance dont l''entrée suivante décrit l''entrée en vigueur", "Si votre entreprise s''est enregistrée à la TVA au cours de 2024, vérifiez laquelle des échéances de cette résolution vous concernait spécifiquement"]');

-- uy-universal-mandate-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-universal-mandate-2025', 'es', 'Entra en vigor la emisión obligatoria universal del CFE, que cierra la ventana de exención', 'En un comunicado oficial publicado el 28 de noviembre de 2024, la DGI anunció que, a partir del 1 de enero de 2025, prácticamente todos los contribuyentes de IVA restantes -- incluidos los del régimen de "IVA Mínimo" -- pasaban a ser emisores electrónicos, cerrando la ventana de exención que el organismo había mantenido en distintas formas desde 2012. Queda una lista breve y definida de excepciones: contribuyentes cuya actividad sea exclusivamente agropecuaria con ingresos anuales inferiores a UI 4.000.000, contribuyentes de IVA que solo presten servicios de construcción con valor agregado, contribuyentes del impuesto a la renta de no residentes (IRNR), actividad totalmente exenta de IVA fuera de las zonas francas, y los regímenes simplificados de microempresas de Uruguay (Monotributo, Monotributo Social MIDES y Aporte Único). El propio anuncio de la DGI informó que la facturación electrónica ya alcanzaba el 98% de la documentación emitida en el país en ese momento -- esta es la fase final de un proceso de digitalización que la DGI inició más de una década antes, no un requisito nuevo y repentino.', '["Si su empresa aún no emitía CFE, confirme que ahora está registrada como emisor electrónico -- la ventana de exención que podría habérsele aplicado se cerró el 1 de enero de 2025", "Verifique si su caso está comprendido en alguna de las escasas exenciones restantes (pequeña agricultura, construcción con valor agregado, IRNR, exención total de IVA, o un régimen simplificado de microempresas) antes de asumir que el mandato se le aplica"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-universal-mandate-2025', 'de', 'Universelle verpflichtende CFE-Ausstellung tritt in Kraft und schließt das Ausnahmefenster', 'In einer am 28. November 2024 veröffentlichten offiziellen Mitteilung gab die DGI bekannt, dass ab dem 1. Januar 2025 praktisch alle verbleibenden Umsatzsteuerpflichtigen -- einschließlich jener unter dem Regime "IVA Mínimo" (Mindest-Umsatzsteuer) -- zu elektronischen Rechnungsstellern wurden, wodurch das Ausnahmefenster geschlossen wurde, das die Behörde seit 2012 in verschiedenen Formen aufrechterhalten hatte. Eine kurze, klar definierte Liste von Ausnahmen bleibt bestehen: Steuerpflichtige, deren Tätigkeit ausschließlich landwirtschaftlich ist und deren Jahreseinkommen unter UI 4.000.000 liegt, umsatzsteuerpflichtige Personen, die ausschließlich wertschöpfende Bauleistungen erbringen, Steuerpflichtige der Einkommensteuer für Gebietsfremde (IRNR), vollständig umsatzsteuerbefreite Tätigkeiten außerhalb von Freihandelszonen, sowie Uruguays vereinfachte Kleinstunternehmerregime (Monotributo, Monotributo Social MIDES und Aporte Único). Die DGI selbst berichtete in ihrer Ankündigung, dass die elektronische Rechnungsstellung zu diesem Zeitpunkt bereits 98 % der im Land ausgestellten Dokumentation erreichte -- dies ist die Abschlussphase eines Digitalisierungsprozesses, den die DGI mehr als ein Jahrzehnt zuvor begonnen hatte, keine plötzliche neue Anforderung.', '["Wenn Ihr Unternehmen noch keine CFE ausgestellt hat, prüfen Sie, ob Sie jetzt als elektronischer Rechnungssteller registriert sind -- das Ausnahmefenster, das möglicherweise für Sie galt, wurde am 1. Januar 2025 geschlossen", "Prüfen Sie, ob Sie unter eine der wenigen verbleibenden Ausnahmen fallen (Kleinlandwirtschaft, wertschöpfende Bauleistungen, IRNR, vollständige Umsatzsteuerbefreiung oder ein vereinfachtes Kleinstunternehmerregime), bevor Sie davon ausgehen, dass die Pflicht für Sie gilt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-universal-mandate-2025', 'fr', 'L''émission obligatoire universelle du CFE entre en vigueur, refermant la fenêtre d''exemption', 'Dans un communiqué officiel publié le 28 novembre 2024, la DGI a annoncé qu''à compter du 1er janvier 2025, la quasi-totalité des contribuables à la TVA restants -- y compris ceux relevant du régime « IVA Mínimo » (TVA minimale) -- deviendraient émetteurs électroniques, refermant la fenêtre d''exemption que l''agence avait maintenue sous diverses formes depuis 2012. Une courte liste définie d''exceptions subsiste : les contribuables dont l''activité est exclusivement agricole avec un revenu annuel inférieur à UI 4 000 000, les assujettis à la TVA n''exerçant que des services de construction à valeur ajoutée, les contribuables de l''impôt sur le revenu des non-résidents (IRNR), les activités entièrement exonérées de TVA hors zones franches, et les régimes simplifiés de micro-entreprises de l''Uruguay (Monotributo, Monotributo Social MIDES et Aporte Único). L''annonce de la DGI elle-même indiquait que la facturation électronique couvrait déjà 98 % de la documentation émise dans le pays à ce moment-là -- il s''agit de la phase finale d''un processus de numérisation entamé par la DGI plus d''une décennie plus tôt, et non d''une nouvelle exigence soudaine.', '["Si votre entreprise n''émettait pas encore de CFE, vérifiez que vous êtes désormais enregistré comme émetteur électronique -- la fenêtre d''exemption qui pouvait s''appliquer à vous s''est refermée le 1er janvier 2025", "Vérifiez si vous relevez de l''une des rares exemptions restantes (petite agriculture, construction à valeur ajoutée, IRNR, exonération totale de TVA, ou un régime simplifié de micro-entreprise) avant de présumer que l''obligation s''applique à vous"]');

-- uy-cfe-v25-controls-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-v25-controls-2026', 'es', 'Entran en vigor los nuevos controles de validación obligatorios del formato CFE v25.1', 'La especificación técnica del CFE de la DGI ha sido revisada en varias ocasiones a lo largo de la historia del sistema -- más recientemente hasta las versiones 25 y 25.1. Nuevos campos de datos y validaciones en varias zonas del esquema entraron en producción el 3 de marzo de 2026, y controles obligatorios más estrictos siguieron el 15 de abril de 2026 para los datos de referencia cruzada y trazabilidad de las facturas (campos de moneda y tipo de cambio) y para la validación del RUC del representante autorizado y del emisor. Se trata de una evolución técnica de rutina del esquema que se suma al mandato ya existente, no de una ampliación de quiénes deben emitir CFE.', '["Confirme que su software de facturación o su proveedor de servicios ha implementado los cambios de campos y validación del formato CFE v25.1 antes de la fecha de controles obligatorios del 15 de abril de 2026", "Si utiliza un proveedor externo de facturación electrónica, pregúntele directamente si está certificado para la versión v25.1 en lugar de asumir la compatibilidad"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-v25-controls-2026', 'de', 'Neue verpflichtende Validierungskontrollen des CFE-Formats v25.1 treten in Kraft', 'Die technische Spezifikation des CFE der DGI wurde im Laufe der Systemgeschichte wiederholt überarbeitet -- zuletzt auf die Versionen 25 und 25.1. Neue Datenfelder und Validierungen in mehreren Schemabereichen gingen am 3. März 2026 in den Produktivbetrieb, und strengere verpflichtende Kontrollen folgten am 15. April 2026 für Querverweis- und Rückverfolgbarkeitsdaten von Rechnungen (Währungs- und Wechselkursfelder) sowie für die Validierung der RUC-Nummer von bevollmächtigten Vertretern und Ausstellern. Dies ist eine routinemäßige technische Weiterentwicklung des Schemas, die auf die bestehende Pflicht aufgesetzt wird, keine Ausweitung des Kreises der zur CFE-Ausstellung Verpflichteten.', '["Bestätigen Sie, dass Ihre Rechnungssoftware oder Ihr Dienstleister die Feld- und Validierungsänderungen des CFE-Formats v25.1 vor dem Termin der verpflichtenden Kontrollen am 15. April 2026 umgesetzt hat", "Wenn Sie einen externen E-Invoicing-Anbieter nutzen, fragen Sie ihn direkt, ob er für v25.1 zertifiziert ist, statt Kompatibilität einfach anzunehmen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('uy-cfe-v25-controls-2026', 'fr', 'Les nouveaux contrôles de validation obligatoires du format CFE v25.1 entrent en vigueur', 'La spécification technique du CFE de la DGI a été révisée à plusieurs reprises au fil de l''histoire du système -- le plus récemment vers les versions 25 et 25.1. De nouveaux champs de données et validations couvrant plusieurs zones du schéma sont entrés en production le 3 mars 2026, et des contrôles obligatoires plus stricts ont suivi le 15 avril 2026 pour les données de référence croisée et de traçabilité des factures (champs de devise et de taux de change) ainsi que pour la validation du RUC du représentant autorisé et de l''émetteur. Il s''agit d''une évolution technique de routine du schéma, venant s''ajouter à l''obligation existante, et non d''un élargissement de qui doit émettre des CFE.', '["Vérifiez que votre logiciel de facturation ou votre prestataire de services a mis en œuvre les modifications de champs et de validation du format CFE v25.1 avant l''échéance des contrôles obligatoires du 15 avril 2026", "Si vous utilisez un prestataire tiers de facturation électronique, demandez-lui directement s''il est certifié pour la v25.1 plutôt que de présumer de la compatibilité"]');
